using EqlTracker.Core;

static class CompactPetTests
{
    public static void Register(Action<string,Action> register)
    {
        void Test(string n,Action f)=>register("Compact Pet · "+n,f);
        static void Check(bool ok,string reason="Assertion failed"){if(!ok)throw new Exception(reason);}
        string path=Path.Combine(AppContext.BaseDirectory,"data/catalog-slot-repairs.json");
        var fixtures=Json.Read<List<PetItemRules.WikiFixture>>(path);
        Test("mixed case slots and effect levels are separate",()=>{var f=fixtures.Single(f=>f.Title=="Spiroc Wingblade");var item=WikiClient.ParseItem(f.Title,f.Text,f.Revision);Check(item.Slots.SequenceEqual(new[]{"PRIMARY","SECONDARY"}));Check(item.RequiredLevel==0&&item.EffectActivationLevel==45&&item.MetadataComplete);});
        foreach(var fixture in fixtures) Test("audited source "+fixture.Title,()=>{var item=WikiClient.ParseItem(fixture.Title,fixture.Text,fixture.Revision);if(fixture.Title is "Stained Parchment Bottom" or "Stained Parchment Top")Check(item.Slots.Count==0&&item.Classes.Contains("NONE"));else if(fixture.Title!="Blood Soaked Plasmatic Priest Robe")Check(item.Slots.Count>0,fixture.Title+" missing slots");});
        Test("slot categories are exact documented fallbacks",()=>{var i=WikiClient.ParseItem("Synthetic","{{Itemstats|statsblock=AC: 3 Class: ALL Race: ALL}} [[Category:Back]] [[Category:Primary]] [[Category:Warrior Equipment]]",1);Check(i.Slots.Contains("BACK")&&i.Slots.Contains("PRIMARY")&&i.Slots.Count==2);});
        Test("offline repair preserves IDs aliases stats and sources",()=>{var c=new Catalog{Items=[new(){Key=Identity.Key("Spiroc Wingblade"),Name="Spiroc Wingblade",GameId=20679,Aliases=["Wingblade alias"],RequiredLevel=45,Revision=171305,MetadataVersion=5,Stats=new(){["AC"]=1},Sources=[new(){Zone="Plane of Sky",Mob="The Spiroc Lord",EvidenceId="classic-wingblade"}]}]};CatalogSlotEvidence.Apply(c,path);var item=c.Find("Spiroc Wingblade")!;Check(item.GameId==20679&&item.RequiredLevel==0&&item.EffectActivationLevel==45&&item.Stats["AC"]==1&&item.Aliases.Contains("Wingblade alias")&&item.Sources.Any(s=>s.EvidenceId=="classic-wingblade"));});
        Test("old checked revisions remain pending with new parser",()=>{string file=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");try{using var cache=new EquipmentCatalog(file);cache.Index(["Spiroc Wingblade"]);cache.Store([], ["Spiroc Wingblade"],PetItemRules.MetadataVersion-1);Check(cache.Pending(DateTime.UtcNow.AddDays(-1)).Contains("Spiroc Wingblade"));cache.Store([], ["Spiroc Wingblade"]);Check(!cache.Pending(DateTime.UtcNow.AddDays(-1)).Contains("Spiroc Wingblade"));}finally{File.Delete(file);}});
        Test("Pet width reset is additive scoped and idempotent",()=>{var p=new CharacterProfile{ColumnWidths=new(){["tracker.pet.candidates:Name"]=500,["tracker.pet.inventory:Type"]=300,["gear-v2:Name"]=450},PanelSplits=new(){["pet-focused-items"]=.6}};Check(PetLayoutDefaults.Apply(p)&&p.ColumnWidths.Count==1&&p.ColumnWidths["gear-v2:Name"]==450&&p.PanelSplits["pet-focused-items"]==.6);p.ColumnWidths["tracker.pet.candidates:Name"]=190;Check(!PetLayoutDefaults.Apply(p)&&p.ColumnWidths.Count==2);var copy=EquipmentPositions.Copy(p);Check(!PetLayoutDefaults.Apply(copy));});
        Test("truncated instruction headings render only full body",()=>{var s=new QuestStep{Name="Give Mahlin's Mystical Bongos to Konia Swiftfoot in Western Karana (guard tower #4), receive Ma",Instructions="Give Mahlin’s Mystical Bongos to Konia Swiftfoot in Western Karana (guard tower #4), receive Maestro's Symphony Page 24 Bottom"};Check(QuestPresentation.Instruction(null,s).Heading=="");});
        Test("source cards group routes while retaining conflicting provenance",()=>{var a=new ItemSource{Zone="Kedge Keep",Mob="Phinigel Autropos",Method="Drop",Availability="Preparation guide",Era="Classic"};var b=new ItemSource{Zone="Kedge Keep",Mob="Phinigel Autropos",Method="Drop",Availability="Wiki documented",Era="Unverified"};var groups=SourcePresentation.Groups([a,b]).ToList();Check(groups.Count==1&&SourcePresentation.Evidence(groups[0]).Contains("Wiki documented")&&SourcePresentation.Evidence(groups[0]).Contains("Preparation guide"));});
        Test("computed card dimensions and deltas use effective equipment",()=>{var p=new CharacterProfile{Loadouts=[new(){Name="Example",Classes=["MAG","WAR","CLR"],Level=50}],SelectedLoadout="Example"};p.PetGoalWeights["DPS"]=new(){["HP"]=2};p.PetGoalWeights["Tank"]=new(){["AC"]=4};var item=new ItemDefinition{Key="test",Name="Test",Classes=["ALL"],Slots=["CHEST"],Stats=new(){["AC"]=10,["HP"]=80},MetadataComplete=true};var c=new Catalog{Items=[item]};var b=new PetBuild{PetType="Earth",PetLevel=41,Items=[new(){Id="x",ItemKey="test",Name="Test",Position=1,Slot="Chest"}]};var summons=new PetContextCatalog{Spells=[new("Earth","Test summon","MAG",40,"https://example.invalid/test",1){BasePetLevel=41},new("Air","Air summon","MAG",40,"https://example.invalid/air",1){BasePetLevel=41}]};var before=System.Text.Json.JsonSerializer.Serialize(b);var rows=PetComparisonEngine.Evaluate(p,b,c,summons,PetBuffCatalog.References(),[],PetEquipmentMode.IntendedSlots,CancellationToken.None);Check(rows.Count==2&&rows.All(r=>r.DamagePreference==160&&r.DefensePreference==40&&r.GearHp==80&&r.GearHpDelta==0&&r.DamagePreferenceDelta==0&&r.DefensePreferenceDelta==0&&r.DisplayDps==null&&r.Hp==null));Check(before==System.Text.Json.JsonSerializer.Serialize(b));});
        Test("Actual and explicit ranks preserve recorded legacy ranks",()=>{var e=new InventoryEntry{Name="Example +14",Count=1};Check(CandidateRanks.Resolve(e,null)==14&&CandidateRanks.Resolve(e,5)==5&&e.Rank==14);});
    }
}
